import re

_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}
_TOKEN = re.compile(r"(\d+)([dhms])")


def parse_duration(text: str) -> int:
    """Convert a duration string such as '1h30m' to total seconds."""
    text = text.strip().lower()
    if not text:
        return 0
    total = 0
    pos = 0
    for match in _TOKEN.finditer(text):
        if match.start() != pos:
            raise ValueError(f"malformed duration: {text!r}")
        total += int(match.group(1)) * _UNIT_SECONDS[match.group(2)]
        pos = match.end()
    if pos != len(text):
        raise ValueError(f"malformed duration: {text!r}")
    return total

import functools
from collections import OrderedDict


def memoize(maxsize: int = 128):
    """Return a decorator caching results with LRU eviction."""

    def decorator(func):
        cache: "OrderedDict" = OrderedDict()

        @functools.wraps(func)
        def wrapper(*args):
            if maxsize <= 0:
                return func(*args)
            if args in cache:
                cache.move_to_end(args)
                return cache[args]
            result = func(*args)
            cache[args] = result
            if len(cache) > maxsize:
                cache.popitem(last=False)
            return result

        wrapper.cache_clear = cache.clear
        return wrapper

    return decorator

import functools
import time
import logging

logger = logging.getLogger(__name__)


def retry(attempts: int = 3, base_delay: float = 0.5):
    """Retry a callable with exponential backoff."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for n in range(attempts):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last_exc = exc
                    logger.warning("attempt %d/%d failed: %s", n + 1, attempts, exc)
                    if n < attempts - 1:
                        time.sleep(base_delay * 2 ** n)
            raise last_exc

        return wrapper

    return decorator

from itertools import islice
from typing import Iterable, Iterator, List


def chunked(iterable: Iterable, size: int) -> Iterator[List]:
    """Yield lists of at most `size` items from any iterable."""
    if size <= 0:
        raise ValueError("size must be a positive integer")
    it = iter(iterable)
    while True:
        batch = list(islice(it, size))
        if not batch:
            return
        yield batch

from typing import Any, Mapping


def safe_get(mapping: Mapping, path: str, default: Any = None) -> Any:
    """Return the value at a dotted `path` in a nested mapping, or `default`."""
    current: Any = mapping
    for key in path.split("."):
        if not isinstance(current, Mapping) or key not in current:
            return default
        current = current[key]
    return current
